theorem nondegenerate_prod [Invertible (2 : R)] {Q₁ : QuadraticForm R M₁}
    {Q₂ : QuadraticForm R M₂} (h₁ : Q₁.Nondegenerate) (h₂ : Q₂.Nondegenerate) :
